CREATE TRIGGER tasks_dates_insert BEFORE INSERT ON tasks WHEN (json_extract(NEW.data,'$.effective_due_on') IS NOT NULL AND (length(json_extract(NEW.data,'$.effective_due_on'))!=10 OR date(json_extract(NEW.data,'$.effective_due_on'),'+0 days') IS NULL OR date(json_extract(NEW.data,'$.effective_due_on'),'+0 days')!=json_extract(NEW.data,'$.effective_due_on'))) OR (json_extract(NEW.data,'$.manual_due_on') IS NOT NULL AND (length(json_extract(NEW.data,'$.manual_due_on'))!=10 OR date(json_extract(NEW.data,'$.manual_due_on'),'+0 days') IS NULL OR date(json_extract(NEW.data,'$.manual_due_on'),'+0 days')!=json_extract(NEW.data,'$.manual_due_on'))) OR (json_extract(NEW.data,'$.computed_due_on') IS NOT NULL AND (length(json_extract(NEW.data,'$.computed_due_on'))!=10 OR date(json_extract(NEW.data,'$.computed_due_on'),'+0 days') IS NULL OR date(json_extract(NEW.data,'$.computed_due_on'),'+0 days')!=json_extract(NEW.data,'$.computed_due_on'))) OR (json_extract(NEW.data,'$.activated_on') IS NOT NULL AND (length(json_extract(NEW.data,'$.activated_on'))!=10 OR date(json_extract(NEW.data,'$.activated_on'),'+0 days') IS NULL OR date(json_extract(NEW.data,'$.activated_on'),'+0 days')!=json_extract(NEW.data,'$.activated_on'))) OR (json_extract(NEW.data,'$.completed_on') IS NOT NULL AND (length(json_extract(NEW.data,'$.completed_on'))!=10 OR date(json_extract(NEW.data,'$.completed_on'),'+0 days') IS NULL OR date(json_extract(NEW.data,'$.completed_on'),'+0 days')!=json_extract(NEW.data,'$.completed_on'))) BEGIN SELECT RAISE(ABORT,'Invalid business date'); END;
